import six


class CommonOptions(object):

    def __init__(self, iperf_path=None, cmd_options=None, adb=None, serial_number=None):
        self._iperf_path = iperf_path
        self._initialize_cmd_options(cmd_options or '')
        self._full_cmd_options_attribute_name_list = [item.strip('--').replace('-', '_') for item in
                                                      self._double_short_dashes() + self._double_unique_short_dashes()]
        self._set_attributes(self._cmd_options)
        self._adb = adb or False
        self._serial_number = serial_number or ''

    def _initialize_cmd_options(self, cmd_options):
        self._cmd_options_str = ''
        if isinstance(cmd_options, six.string_types):
            self._cmd_options = self.create_command_option_dict(cmd_options)
            self._cmd_options_str = cmd_options
        elif isinstance(cmd_options, dict):
            self._cmd_options = cmd_options
        else:
            raise AttributeError('cmd_options parameter must be type of str or dict')
        return self._cmd_options

    @property
    def iperf_path(self):
        return self._iperf_path

    @property
    def serial_number(self):
        return self._serial_number

    @property
    def adb_shell(self):
        return self._adb

    @property
    def server_ip(self):
        raise NotImplementedError

    @staticmethod
    def _is_false(value):
        value = str(value)
        false_values = [False, 'False', 'FALSE', 'false', 'No', 'no', 'NO']
        return value in false_values

    @staticmethod
    def _is_true(value):
        value = str(value)
        true_values = [True, 'True', 'TRUE', 'true', 'Yes', 'yes', 'YES']
        return value in true_values

    def _try_cast_to_bool(self, value):
        if self._is_false(value):
            return False
        if self._is_true(value):
            return True
        return value

    def _get_config_value(self, config_key, default_value=''):
        return self._cmd_options.get(config_key, default_value)

    def get_option_arg_list(self):
        option_list = []
        for name_without_dash, value in self._cmd_options.items():
            option_name = '--{option}'.format(option=name_without_dash)
            option_name = option_name.strip()

            if self._is_true(value):
                option_list.append(option_name)
            elif not self._is_false(value):
                option_list.append(option_name)
                option_list.append(str(value).strip())
            else:
                continue
        return option_list

    def __str__(self):
        if self._cmd_options_str:
            return ' ' + self._cmd_options_str.strip()
        cmd = ""
        for option in self._get_cmd_option_values():
            cmd += option
        return cmd

    @classmethod
    def _short_dashes(cls):
        raise NotImplementedError

    @classmethod
    def _double_short_dashes(cls):
        raise NotImplementedError

    @classmethod
    def _double_unique_short_dashes(cls):
        raise NotImplementedError

    @classmethod
    def _split_options(cls, options_str):
        """
        separate options string by ' ', support "" in value
        """
        if not options_str:
            return []

        options_list = cls._replace_blank_in_double_quotation(options_str.strip()).split(' ')
        for index in range(0, len(options_list)):
            options_list[index] = options_list[index].replace('#', ' ')
        return options_list

    @classmethod
    def _replace_blank_in_double_quotation(cls, s, c='#'):
        odd = False
        char_list = []
        for index in range(0, len(s)):
            if odd:
                be_added_char = s[index]
                if s[index] == ' ':
                    be_added_char = c

                elif s[index] == '"':
                    odd = False

                char_list.append(be_added_char)
            else:
                if s[index] == '"':
                    odd = True
                char_list.append(s[index])
        return "".join(char_list)

    @classmethod
    def create_command_option_dict(cls, options_str):  # noqa: C901
        short_to_double = dict(zip(cls._short_dashes(), cls._double_short_dashes()))
        options_list = cls._split_options(options_str)

        option_dict_without_dash = {}

        options_count = len(options_list)
        value = ""
        for index in reversed(range(0, options_count)):
            arg = options_list[index]
            if arg.startswith('--'):
                if arg not in cls._double_short_dashes() + cls._double_unique_short_dashes():
                    raise AttributeError('not support option "{}" in iperf'.format(arg))
                key = arg.strip('--')
                option_dict_without_dash[key] = value
                value = ""
            elif arg.startswith('-'):
                if arg not in cls._short_dashes():
                    raise AttributeError('not support option "{}" in iperf'.format(arg))
                key = short_to_double[arg].strip('--')
                option_dict_without_dash[key] = value
                value = ""
            else:
                if not arg:
                    raise AttributeError('"" or empty should not be option')
                value = arg

        for k, v in option_dict_without_dash.items():
            if not v:
                option_dict_without_dash[k] = True

        return option_dict_without_dash

    def _set_attributes(self, dic):
        attribute_names = []
        for k, v in dic.items():
            attribute_name = k.replace('-', '_')
            attribute_value = self._try_cast_to_bool(v)
            setattr(self, attribute_name, attribute_value)
            attribute_names.append(attribute_name)
        return attribute_names

    def _get_cmd_option_values(self):
        option_list = []
        for name_without_dash, value in self._cmd_options.items():
            if self._is_true(value):
                option_str = ' --{option}'.format(option=name_without_dash)
            elif not self._is_false(value):
                option_str = ' --{option} {value}'.format(option=name_without_dash, value=value)
            else:
                continue
            option_list.append(option_str)
        return option_list

    def __getattr__(self, item):
        if item in self._full_cmd_options_attribute_name_list:
            return ''
        raise AttributeError(item)


class Iperf2Options(CommonOptions):

    def __init__(self, iperf_path=None, cmd_options=None, adb=None, serial_number=None):
        self._iperf2_path = iperf_path or 'iperf'
        super(Iperf2Options, self).__init__(iperf_path=self._iperf2_path,
                                            cmd_options=cmd_options,
                                            adb=adb,
                                            serial_number=serial_number)

    def is_iperf3(self):
        return False

    @classmethod
    def _short_dashes(cls):
        return ['-u', '-i', '-p', '-b', '-l', '-V', '-B', '-w', '-z', '-m', '-o', '-C', '-M', '-N', '-S', '-f', '-e',
                '-x', '-y', ]

    @classmethod
    def _double_short_dashes(cls):
        return ['--udp', '--interval', '--port', '--bandwidth', '--len', '--ipv6_domain', '--bind',
                '--window', '--realtime', '--print_mss', '--output', '--compatibility', '--mss', '--nodelay', '--tos',
                '--format', '--enhancedreports', '--reportexclude', '--reportstyle', ]

    @classmethod
    def _double_unique_short_dashes(cls):
        return ['--udp-counters-64bit', ]


class Iperf2ServerOptions(Iperf2Options):

    def _initialize_cmd_options(self, cmd_options):
        super(Iperf2ServerOptions, self)._initialize_cmd_options(cmd_options)
        self._cmd_options['server'] = True

    def is_server_options(self):
        return True

    @property
    def server_ip(self):
        return self.bind if hasattr(self, 'bind') else ''

    @classmethod
    def _short_dashes(cls):
        return Iperf2Options._short_dashes() + ['-s', '-t', '-H', '-U', ]

    @classmethod
    def _double_short_dashes(cls):
        return Iperf2Options._double_short_dashes() + ['--server', '--time', '--ssm-host', '--single_udp']

    @classmethod
    def _double_unique_short_dashes(cls):
        return Iperf2Options._double_unique_short_dashes() + ['--udp-histogram', ]


class Iperf2ClientOptions(Iperf2Options):

    def is_server_options(self):
        return False

    @property
    def server_ip(self):
        return self.client

    @classmethod
    def _short_dashes(cls):
        return Iperf2Options._short_dashes() + ['-c', '-P', '-d', '-t', '-T', '-n', '-r', '-F', '-I', '-L', '-Z']

    @classmethod
    def _double_short_dashes(cls):
        return Iperf2Options._double_short_dashes() + ['--client', '--parallel', '--dualtest', '--time', '--ttl',
                                                       '--num', '--tradeoff', '--fileinput', '--stdin', '--listenport',
                                                       '--linux-congestion']

    @classmethod
    def _double_unique_short_dashes(cls):
        return Iperf2Options._double_unique_short_dashes() + ['--ipg', '--isochronous']


class Iperf3Options(CommonOptions):

    def __init__(self, iperf_path=None, cmd_options=None, adb=None, serial_number=None):
        self._iperf3_path = iperf_path or 'iperf3'
        super(Iperf3Options, self).__init__(iperf_path=self._iperf3_path,
                                            cmd_options=cmd_options,
                                            adb=adb,
                                            serial_number=serial_number)

    def is_iperf3(self):
        return True

    @classmethod
    def _short_dashes(cls):
        return ['-i', '-p', '-B', '-f', '-d', '-J', '-V', '-A', '-F']

    @classmethod
    def _double_short_dashes(cls):
        return ['--interval', '--port', '--bind', '--format', '--debug', '--json', '--verbose', '--affinity', '--file']

    @classmethod
    def _double_unique_short_dashes(cls):
        return ['--logfile', '--forceflush', ]


